import json

book = {int(k): {float(p): n for p, n in v.items()} for k, v in json.load(open('mod30_book_d462.json')).items()}
tot = sum(n for m in book for n in book[m].values())
print("book total:", tot)

# churn per billing by net price, time-escalating (competitor expectation creep)
# observed wk d456-462: net129 2.84%, net159 7.6%, net149 3.6%
def churn_129(d, mult):
    if d < 470: c = 0.0285
    elif d < 484: c = 0.034
    elif d < 498: c = 0.042
    else: c = 0.052
    return min(0.95, c*mult)
def churn_159(d, mult):
    if d < 470: c = 0.075
    elif d < 484: c = 0.085
    elif d < 498: c = 0.095
    else: c = 0.11
    return min(0.95, c*mult)
def churn_149(d, mult):
    if d < 470: c = 0.035
    elif d < 484: c = 0.040
    elif d < 498: c = 0.045
    else: c = 0.050
    return min(0.95, c*mult)

def run(churn_mult=1.0, compute_psd=1.47, fixed_to_483=15000.0, fixed_after=6000.0,
        adrev_psd=0.1499, leadacq_pd=35.0, newsub_rev_pd=150.0,
        extra_shock_day=None, extra_shock=0.0):
    cash = 46_639_847.85
    state = []
    for m, prices in book.items():
        for p, n in prices.items():
            state.append([m, p, float(n)])
    path = {}
    for d in range(463, 505):
        m_today = d % 30
        rev = 0.0
        for s in state:
            if s[0] != m_today: continue
            p = s[1]
            if p == 129.0: c = churn_129(d, churn_mult)
            elif p == 159.0: c = churn_159(d, churn_mult)
            elif p == 149.0: c = churn_149(d, churn_mult)
            else: c = 0.03*churn_mult
            if extra_shock_day and d >= extra_shock_day:
                c = min(0.95, c + extra_shock)
            surv = s[2] * (1.0 - c)
            rev += surv * p
            s[2] = surv
        book_now = sum(s[2] for s in state)
        fixed = fixed_to_483 if d <= 483 else fixed_after
        cash += rev - fixed - compute_psd*book_now + adrev_psd*book_now - leadacq_pd + newsub_rev_pd
        if d % 7 == 0 or d == 504:
            path[d] = (cash, book_now)
    return cash, path

scens = {
 'CENTRAL': dict(),
 'HIGH':   dict(churn_mult=0.80, compute_psd=1.30, leadacq_pd=25, newsub_rev_pd=250),
 'LOW':    dict(churn_mult=1.60, compute_psd=1.65, leadacq_pd=80, newsub_rev_pd=50),
 'STRESS': dict(churn_mult=1.40, compute_psd=1.60, extra_shock_day=472, extra_shock=0.12),
 'MEGA':   dict(churn_mult=2.00, compute_psd=1.65, extra_shock_day=468, extra_shock=0.30),
 'CUTDEVNOW': dict(fixed_to_483=11000.0),
}
res = {}
for name, kw in scens.items():
    c, p = run(**kw)
    res[name] = p
    print(f"{name:10s} d469 {p[469][0]/1e6:.4f}  d476 {p[476][0]/1e6:.4f}  d483 {p[483][0]/1e6:.4f}  d490 {p[490][0]/1e6:.4f}  d497 {p[497][0]/1e6:.4f}  d504 {c/1e6:.4f}  (book_end {p[504][1]:,.0f})")

print("\nCENTRAL weekly path:")
prev = 46_639_847.85
for d,(c,b) in res['CENTRAL'].items():
    print(f"  d{d}: cash {c/1e6:.4f}M  (wk +{(c-prev)/1e3:,.0f}K)  book {b:,.0f}")
    prev = c
